CREATE DATABASE IF NOT EXISTS senati_multijugador CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE senati_multijugador;
CREATE TABLE usuarios(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,username VARCHAR(32) NOT NULL UNIQUE,correo VARCHAR(190) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,fecha_creacion TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE historial_sesiones(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,usuario_id BIGINT UNSIGNED NOT NULL,fecha_hora_ingreso TIMESTAMP DEFAULT CURRENT_TIMESTAMP,ip_o_dispositivo VARCHAR(255) NOT NULL,FOREIGN KEY(usuario_id) REFERENCES usuarios(id) ON DELETE CASCADE,INDEX(usuario_id,fecha_hora_ingreso)) ENGINE=InnoDB;